// Gate + normalise a clip order. Anyone on the internet can reach this webhook
// (/webhook/ bypasses nginx basic auth for Telegram), and whatever passes is
// HMAC-signed and handed to a Hermes agent that has a terminal. So: caller must
// present X-Clip-Token, and every field is bounded before it reaches the prompt.
// Rejections return ok:false (answered 401/400 by "Respond accepted") instead of
// throwing, so a stranger hammering the URL cannot spam the Error Alerter.
const { createHash, timingSafeEqual } = require('crypto');
const item = $input.first().json;
const b = item.body || {};
const h = item.headers || {};
const reject = (code, reason) => [{ json: { ok: false, code, reason } }];
const digest = (s) => createHash('sha256').update(String(s)).digest();

const want = $env.CLIP_INTAKE_TOKEN;
if (!want) return reject(401, 'intake token is not configured');   // fail closed
if (!timingSafeEqual(digest(h['x-clip-token'] || ''), digest(want))) return reject(401, 'bad token');

const str = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);

const product = str(b.product, 200);
if (!product) return reject(400, 'product is required');

const link = str(b.link, 300);
const m = /^https:\/\/([a-z0-9.-]+)(?::443)?(?:[/?#]|$)/i.exec(link);
const host = m ? m[1].toLowerCase() : '';
if (!(host === 'shopee.co.th' || host.endsWith('.shopee.co.th') || host === 'shope.ee')) {
  return reject(400, 'link must be an https shopee.co.th / shope.ee URL');
}

const duration_s = Math.round(Number(b.duration_s ?? 10));
if (!(duration_s >= 5 && duration_s <= 60)) return reject(400, 'duration_s must be 5-60');

const category = str(b.category || 'gadget', 30);
if (!/^[a-z0-9_-]+$/i.test(category)) return reject(400, 'category must be [a-z0-9_-]');

// Images are paths on the Hermes box; only the scratch area is allowed.
const IMAGE_DIR = '/opt/data/cache/scratch/';
const raw = Array.isArray(b.images) ? b.images : [];
if (raw.length > 6) return reject(400, 'at most 6 images');
const images = [];
for (const p of raw) {
  const s = str(p, 300);
  if (!s.startsWith(IMAGE_DIR) || s.split('/').includes('..')) {
    return reject(400, 'images must be under ' + IMAGE_DIR);
  }
  images.push(s);
}

return [{ json: { ok: true, job_id: 'clip_' + Date.now(), product, link, duration_s, category,
  images, note: str(b.note, 500), requested_by: str(b.requested_by || 'n8n', 40),
  received_at: new Date().toISOString() } }];

const job = $('Record job').item.json;
if (!job.ok) return [{ json: { skipped: true, code: job.code, reason: job.reason } }];
const { ok, ...payload } = job;
const body = JSON.stringify(payload);
const ts = Math.floor(Date.now() / 1000).toString();
const secret = $env.HERMES_CLIP_WEBHOOK_SECRET;
if (!secret) throw new Error('HERMES_CLIP_WEBHOOK_SECRET is not in the n8n container env');
const { createHmac } = require('crypto');
const https = require('https');
const sig = createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
const result = await new Promise((resolve, reject) => {
  const req = https.request({ hostname: 'fixhardez.synology.me', port: 443,
      path: '/webhooks/clip', method: 'POST', headers: {
      'Content-Type': 'application/json',
      'X-Webhook-Timestamp': ts,
      'X-Webhook-Signature-V2': sig,
      'Content-Length': Buffer.byteLength(body) } }, (resp) => {
    let data = '';
    resp.on('data', (c) => data += c);
    resp.on('end', () => resolve({ status: resp.statusCode, text: data }));
  });
  req.setTimeout(20000, () => req.destroy(new Error('Hermes did not answer within 20 s')));
  req.on('error', reject);
  req.write(body);
  req.end();
});
if (result.status !== 202 && result.status !== 200) {
  throw new Error('Hermes responded ' + result.status + ': ' + result.text.slice(0, 200));
}
return [{ json: { job_id: job.job_id, hermes_status: result.status, hermes_response: result.text.slice(0, 200) } }];

const b = $input.first().json.body || $input.first().json;
return [{json: {job_id: 'clip_' + Date.now(), product: b.product || '', link: b.link || '',
  duration_s: Number(b.duration_s) || 10, category: b.category || 'gadget',
  images: Array.isArray(b.images) ? b.images : [], note: b.note || '',
  requested_by: b.requested_by || 'n8n', received_at: new Date().toISOString()}}];

const job = $('Record job').item.json;
const body = JSON.stringify(job);
const ts = Math.floor(Date.now() / 1000).toString();
const secret = $env.HERMES_CLIP_WEBHOOK_SECRET;
if (!secret) throw new Error('HERMES_CLIP_WEBHOOK_SECRET is not in the n8n container env');
const { createHmac } = require('crypto');
const https = require('https');
const sig = createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
const result = await new Promise((resolve, reject) => {
  const req = https.request({ hostname: 'fixhardez.synology.me', port: 443,
      path: '/webhooks/clip', method: 'POST', headers: {
      'Content-Type': 'application/json',
      'X-Webhook-Timestamp': ts,
      'X-Webhook-Signature-V2': sig,
      'Content-Length': Buffer.byteLength(body) } }, (resp) => {
    let data = '';
    resp.on('data', (c) => data += c);
    resp.on('end', () => resolve({ status: resp.statusCode, text: data }));
  });
  req.on('error', reject);
  req.write(body);
  req.end();
});
if (result.status !== 202 && result.status !== 200) {
  throw new Error('Hermes responded ' + result.status + ': ' + result.text.slice(0, 200));
}
return [{ json: { job_id: job.job_id, hermes_status: result.status, hermes_response: result.text.slice(0, 200) } }];
